#!/usr/bin/env python3
def decrypt(ct):
    res = []
    for i, ch in enumerate(ct):
        if ch.isalpha():
            e = ord(ch.upper()) - 65
            p = (e - i) % 26
            res.append(chr(p + 65))
        else:
            res.append(ch)
    return ''.join(res)

